UPDATE t_teacher_invitation
SET status = 'USED', used_by = #{userId}, used_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'
  AND expires_at > #{now}

UPDATE t_teacher_invitation
SET status = 'REVOKED'
WHERE id = #{id}
  AND status = 'PENDING'
  AND expires_at > #{now}
